link.script:
(function() {
  var token = null;
  var loginType = null;
  var cachedUser = null;
  try {
    token = localStorage.getItem('accessToken');
    loginType = localStorage.getItem('loginType');
    var raw = localStorage.getItem('FILA_DL_USER');
    if (raw) cachedUser = JSON.parse(raw);
  } catch(e) {}

  var isLoggedIn = Boolean(token);
  var u = cachedUser || {};
  var shouldPushPageView = !isLoggedIn || Boolean(u.user_id);

  if (shouldPushPageView) {
    FilaDL.push({
      event: 'ga4_page_view',
      property: {
        brand_sub: 'FILA',
        device: FilaDL.getDeviceType(),
        grades: u.grades || null,
        lifetime_value: u.lifetime_value || null,
        logged_in: isLoggedIn ? 'Y' : 'N',
        login_type: isLoggedIn ? (loginType || null) : null,
        order_count: u.order_count || null,
        registration_date: u.registration_date || null,
        ud_01: u.ud_01 || 'C0',
        ud_02: u.ud_02 || 'K0',
        ud_03: u.ud_03 || 'E0',
        user_id: u.user_id || null,
        page_type: "404",
        search_term_naver: null,
        search_term: null,
        previous_search_term_naver: null
      }
    });
  }

  window.__GA4_PAGE_VIEW_PUSHED = shouldPushPageView;
})();

meta.script:
// 모바일 핀치줌/더블탭 확대 방지 (iOS Safari + Android)
document.addEventListener('gesturestart', function(e) { e.preventDefault(); }, { passive: false });
document.addEventListener('gesturechange', function(e) { e.preventDefault(); }, { passive: false });
var lastTouchEnd = 0;
document.addEventListener('touchend', function(e) {
  var now = Date.now();
  if (now - lastTouchEnd <= 300) { e.preventDefault(); }
  lastTouchEnd = now;
}, { passive: false });

// 전체 우클릭 방지 (개발자 도구 접근 및 이미지 URL 갈취 방어)
document.addEventListener('contextmenu', function(e) {
  e.preventDefault();
});

// 크롬 모바일 감지 (Android + iOS)
(function () {
  var ua = navigator.userAgent;
  var isMobile = /Android|iPhone|iPad|iPod/i.test(ua);
  var isChrome = /Chrome|CriOS/i.test(ua) && !/Edge|Edg|OPR|Opera/i.test(ua);
  if (isMobile && isChrome) {
    document.documentElement.classList.add('chrome-mobile');
  }
})();

