div.script:
(function () {
  const bars = document.querySelectorAll('[data-announcement-bar]');

  function updateAnnouncementHeight() {
    const section = document.querySelector('.announcement-bar-section');
    const height = section && !section.querySelector('.utility-bar.hidden') ? section.offsetHeight : 0;
    document.documentElement.style.setProperty('--announcement-bar-height', height + 'px');
  }

  function hideBar(bar) {
    const utilityBar = bar.closest('.utility-bar');
    if (utilityBar) utilityBar.classList.add('hidden');
    else bar.classList.add('hidden');
    updateAnnouncementHeight();
  }

  // 초기 높이 설정
  updateAnnouncementHeight();
  window.addEventListener('resize', updateAnnouncementHeight);

  bars.forEach((bar) => {
    const utilityBar = bar.closest('.utility-bar');
    const closeBtn = utilityBar ? utilityBar.querySelector('[data-announcement-close]') : bar.querySelector('[data-announcement-close]');
    const storageKey = bar.getAttribute('data-storage-key') || 'announcementBarClosed';

    // 종료일 체크 (CDN 캐시 대응)
    const scheduleEnd = bar.getAttribute('data-schedule-end');
    if (scheduleEnd) {
      const endTime = new Date(scheduleEnd).getTime();
      if (!isNaN(endTime) && Date.now() > endTime) {
        hideBar(bar);
        return;
      }
    }

    // 닫은 날짜(로컬 YYYY-MM-DD)와 오늘이 같으면 숨김. 자정 지나면 재노출.
    function getLocalDateStr(d) {
      const y = d.getFullYear();
      const m = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      return y + '-' + m + '-' + day;
    }
    // 이전 content hash로 저장된 orphan 키 정리 (현재 storageKey 제외)
    const orphanPrefix = storageKey.replace(/-[a-f0-9]{32}$/, '-');
    if (orphanPrefix !== storageKey) {
      for (let i = localStorage.length - 1; i >= 0; i--) {
        const k = localStorage.key(i);
        if (k && k.startsWith(orphanPrefix) && k !== storageKey) {
          localStorage.removeItem(k);
        }
      }
    }

    const todayStr = getLocalDateStr(new Date());
    const stored = localStorage.getItem(storageKey);
    if (stored) {
      if (stored === todayStr) {
        hideBar(bar);
        return;
      }
      // 다른 날 → 정리
      localStorage.removeItem(storageKey);
    }

    if (closeBtn) {
      closeBtn.addEventListener('click', function () {
        hideBar(bar);
        localStorage.setItem(storageKey, getLocalDateStr(new Date()));
      });
    }
  });
})();

header.script:
document.addEventListener("DOMContentLoaded", () => {
  const header = document.querySelector("[data-header-wrapper]");
  if (!header) return;

  const menuList = header.querySelector(".list-menu--inline");
  const megaMenus = header.querySelectorAll("details.mega-menu");
  if (!menuList || !megaMenus.length) return;

  // header--white 클래스가 추가되었는지 추적 (showWhiteHeader에서 추가한 경우에만 복구)
  let wasTransparentBeforeHover = false;

  const showWhiteHeader = () => {
    // Visual System은 메타오브젝트의 배경색을 유지
    if (header.classList.contains("header-wrapper--visual-system")) {
      header.classList.remove("header--white");
      wasTransparentBeforeHover = false;
      return;
    }

    // transparent 헤더일 때만 흰색 배경으로 변경
    if (header.classList.contains("header-wrapper--transparent")) {
      wasTransparentBeforeHover = true;
      header.classList.remove("header-wrapper--transparent");
      header.classList.add("header--white");
    }
  };

  const hideWhiteHeader = () => {
    if (header.classList.contains("header-wrapper--visual-system")) {
      header.classList.remove("header--white");
      wasTransparentBeforeHover = false;
      return;
    }

    // showWhiteHeader에서 변경한 경우에만 복구
    if (!wasTransparentBeforeHover) return;

    // showWhiteHeader에서 transparent를 제거했으므로 복구
    header.classList.add("header-wrapper--transparent");
    header.classList.remove("header--white");
    wasTransparentBeforeHover = false;
  };

  // hover open/close는 HeaderMenu custom element 한 곳에서만 처리
  megaMenus.forEach((menu) => {
    // GNB가 열릴 때만 흰색 배경 표시
    menu.addEventListener("toggle", () => {
      if (menu.open) {
        showWhiteHeader();
      } else {
        // 메뉴 전환 시 close → open 사이 배경이 한 프레임 깜박이지 않도록 지연 확인
        requestAnimationFrame(() => {
          const anyMenuOpen = Array.from(megaMenus).some((item) => item.open);
          if (!anyMenuOpen) hideWhiteHeader();
        });
      }
    });
  });

  // 메뉴 외부 클릭 시 초기화
  document.addEventListener("click", (e) => {
    if (!header.contains(e.target)) {
      megaMenus.forEach((menu) => {
        if (menu.open) menu.open = false;
      });
      hideWhiteHeader();
    }
  });
});

// Mega Menu Slider
document.addEventListener('DOMContentLoaded', function() {
  // Desktop mega menu sliders
  document.querySelectorAll('[data-mega-slider]').forEach(function(slider) {
    const track = slider.querySelector('[data-mega-slider-track]');
    const slides = slider.querySelectorAll('[data-mega-slide]');
    const totalSlides = parseInt(slider.getAttribute('data-total-slides')) || slides.length;
    const labelEl = slider.parentElement.querySelector('[data-mega-slider-label]');
    let currentIndex = 0;
    let autoSlideInterval;
    let isTransitioning = false;

    // 무한 루프를 위해 첫 번째 슬라이드 복제
    if (slides.length > 1 && track) {
      const firstClone = slides[0].cloneNode(true);
      firstClone.setAttribute('data-clone', 'true');
      track.appendChild(firstClone);
    }

    function goToSlide(index, instant) {
      currentIndex = index;
      if (track) {
        if (instant) {
          track.style.transition = 'none';
        } else {
          track.style.transition = 'transform 0.5s ease';
        }
        track.style.transform = 'translateX(-' + (index * 100) + '%)';

        if (instant) {
          // 강제 리플로우 후 트랜지션 복원
          track.offsetHeight;
          track.style.transition = 'transform 0.5s ease';
        }
      }
      // 카운터 업데이트 (실제 슬라이드 개수 기준)
      const displayIndex = index >= slides.length ? 0 : index;
      slides.forEach(function(slide) {
        const counter = slide.querySelector('[data-current-slide]');
        if (counter) {
          counter.textContent = displayIndex + 1;
        }
      });

      // 라벨 텍스트 업데이트
      if (labelEl) {
        const activeSlide = slides[displayIndex];
        if (activeSlide) {
          const text = activeSlide.getAttribute('data-label') || '';
          const link = activeSlide.getAttribute('data-label-link') || '';
          const color = activeSlide.getAttribute('data-label-color') || '#000000';
          labelEl.style.setProperty('--mega-menu-featured-label-color', color);
          if (text) {
            labelEl.innerHTML = link
              ? '' + text + ''
              : text;
          }
        }
      }
    }

    function nextSlide() {
      if (isTransitioning) return;
      isTransitioning = true;

      const next = currentIndex + 1;
      goToSlide(next);

      // 복제 슬라이드에 도달하면 실제 첫 번째 슬라이드로 점프
      if (next >= slides.length) {
        setTimeout(function() {
          goToSlide(0, true);
          isTransitioning = false;
        }, 500);
      } else {
        setTimeout(function() {
          isTransitioning = false;
        }, 500);
      }
    }

    function prevSlide() {
      if (isTransitioning) return;
      const prev = (currentIndex - 1 + slides.length) % slides.length;
      goToSlide(prev);
    }

    function startAutoSlide() {
      autoSlideInterval = setInterval(nextSlide, 2000);
    }

    function stopAutoSlide() {
      clearInterval(autoSlideInterval);
    }

    // 드래그 기능 추가
    let isDragging = false;
    let startX = 0;
    let hasDragged = false;

    slider.addEventListener('mousedown', function(e) {
      if (e.button !== 0) return;
      e.preventDefault();
      isDragging = true;
      hasDragged = false;
      startX = e.clientX;
      stopAutoSlide();
      slider.style.cursor = 'grabbing';
      if (track) track.style.transition = 'none';
    });

    document.addEventListener('mousemove', function(e) {
      if (!isDragging) return;
      const diff = e.clientX - startX;
      if (Math.abs(diff) > 10) {
        hasDragged = true;
      }
    });

    document.addEventListener('mouseup', function(e) {
      if (!isDragging) return;
      isDragging = false;
      slider.style.cursor = 'grab';
      if (track) track.style.transition = 'transform 0.5s ease';

      if (hasDragged) {
        const diff = e.clientX - startX;
        if (diff > 30) {
          prevSlide();
        } else if (diff < -30) {
          nextSlide();
        }
      }
      hasDragged = false;
      startAutoSlide();
    });

    // 이미지 드래그 방지
    slider.querySelectorAll('img').forEach(function(img) {
      img.draggable = false;
    });

    // 클릭 이벤트 방지 (드래그 중)
    slider.addEventListener('click', function(e) {
      if (hasDragged) {
        e.preventDefault();
        e.stopPropagation();
      }
    }, true);

    if (slides.length > 1) {
      startAutoSlide();
      slider.style.cursor = 'grab';
      slider.addEventListener('mouseenter', stopAutoSlide);
      slider.addEventListener('mouseleave', function() {
        if (!isDragging) startAutoSlide();
      });
    }
  });

  // Mobile drawer sliders
  document.querySelectorAll('[data-drawer-slider]').forEach(function(slider) {
    const track = slider.querySelector('[data-drawer-slider-track]');
    const slides = slider.querySelectorAll('[data-drawer-slide]');
    const totalSlides = parseInt(slider.getAttribute('data-total-slides')) || slides.length;
    let currentIndex = 0;
    let autoSlideInterval;
    let isTransitioning = false;

    // 무한 루프를 위해 첫 번째 슬라이드 복제
    if (slides.length > 1 && track) {
      const firstClone = slides[0].cloneNode(true);
      firstClone.setAttribute('data-clone', 'true');
      track.appendChild(firstClone);
    }

    function goToSlide(index, instant) {
      currentIndex = index;
      if (track) {
        if (instant) {
          track.style.transition = 'none';
        } else {
          track.style.transition = 'transform 0.5s ease';
        }
        track.style.transform = 'translateX(-' + (index * 100) + '%)';

        if (instant) {
          track.offsetHeight;
          track.style.transition = 'transform 0.5s ease';
        }
      }
      // 카운터 업데이트 (실제 슬라이드 개수 기준)
      const displayIndex = index >= slides.length ? 0 : index;
      slides.forEach(function(slide) {
        const counter = slide.querySelector('[data-current-slide]');
        if (counter) {
          counter.textContent = displayIndex + 1;
        }
      });
    }

    function nextSlide() {
      if (isTransitioning) return;
      isTransitioning = true;

      const next = currentIndex + 1;
      goToSlide(next);

      if (next >= slides.length) {
        setTimeout(function() {
          goToSlide(0, true);
          isTransitioning = false;
        }, 500);
      } else {
        setTimeout(function() {
          isTransitioning = false;
        }, 500);
      }
    }

    function prevSlide() {
      if (isTransitioning) return;
      const prev = (currentIndex - 1 + slides.length) % slides.length;
      goToSlide(prev);
    }

    function startAutoSlide() {
      autoSlideInterval = setInterval(nextSlide, 2000);
    }

    function stopAutoSlide() {
      clearInterval(autoSlideInterval);
    }

    // 터치 드래그 기능 추가
    let touchStartX = 0;
    let touchStartY = 0;
    let isSwiping = false;

    slider.addEventListener('touchstart', function(e) {
      touchStartX = e.touches[0].clientX;
      touchStartY = e.touches[0].clientY;
      isSwiping = false;
      stopAutoSlide();
      if (track) track.style.transition = 'none';
    }, { passive: true });

    slider.addEventListener('touchmove', function(e) {
      if (!touchStartX) return;
      const diffX = e.touches[0].clientX - touchStartX;
      const diffY = e.touches[0].clientY - touchStartY;

      // 수평 스와이프인지 확인
      if (Math.abs(diffX) > Math.abs(diffY) && Math.abs(diffX) > 10) {
        isSwiping = true;
        e.preventDefault();
      }
    }, { passive: false });

    slider.addEventListener('touchend', function(e) {
      if (track) track.style.transition = 'transform 0.5s ease';

      if (isSwiping) {
        const touchEndX = e.changedTouches[0].clientX;
        const diff = touchEndX - touchStartX;

        if (diff > 30) {
          prevSlide();
        } else if (diff < -30) {
          nextSlide();
        }
      }

      touchStartX = 0;
      touchStartY = 0;
      isSwiping = false;
      setTimeout(startAutoSlide, 2000);
    });

    if (slides.length > 1) {
      startAutoSlide();
    }
  });
});

// dataLayer: gnb_menu — GNB 메뉴 클릭 추적
document.addEventListener('DOMContentLoaded', function() {
