    });
  });
});

div.script:
(function() {
  const drawer = document.querySelector('header-drawer');
  if (!drawer) return;

  // 카카오톡 등 인앱 브라우저에서 안정적인 뷰포트 높이 설정
  function setStableViewportHeight() {
    const vh = window.innerHeight;
    document.documentElement.style.setProperty('--stable-vh', `${vh}px`);
  }

  // 초기 설정
  setStableViewportHeight();

  // 드로워가 열릴 때만 높이 갱신 (스크롤 중에는 갱신하지 않음)
  // 스크롤 위치 저장/복원은 global.js HeaderDrawer 클래스에서 처리
  const details = drawer.querySelector('details');
  if (details) {
    details.addEventListener('toggle', function() {
      if (this.open) {
        // 드로워 열릴 때 현재 뷰포트 높이로 고정
        setStableViewportHeight();
      }
    });
  }

  // 로컬 스토리지 accessToken 체크하여 로그인/로그아웃 버튼 업데이트
  const accountLink = document.getElementById('menu-drawer-account-link');
  const accountText = document.getElementById('menu-drawer-account-text');
  const signupLink = document.getElementById('menu-drawer-signup-link');
  if (accountLink && accountText) {
    const accessToken = localStorage.getItem('accessToken');
    if (accessToken) {
      accountLink.href = '/pages/account/logout';
      accountText.textContent = '로그아웃';
      if (signupLink) signupLink.style.display = 'none';
    } else {
      // returnUrl 중첩 방지: 인증 페이지면 기존 returnUrl 유지(없으면 홈), 그 외엔 현재 경로만
      const authParams = new URLSearchParams(window.location.search);
      const authPath = window.location.pathname;
      const isAuthPage = authPath.startsWith('/account/login') || authPath.startsWith('/account/register');
      const priorReturn = authParams.get('returnUrl') || '';
      // 기존 returnUrl이 또 인증 페이지를 가리키면(중첩 잔재) 홈으로 폴백
      const priorIsAuth = priorReturn.indexOf('/account/login') !== -1 || priorReturn.indexOf('/account/register') !== -1;
      const returnTarget = isAuthPage ? (priorReturn && !priorIsAuth ? priorReturn : '/') : authPath + window.location.search;
      const currentUrl = encodeURIComponent(returnTarget);
      accountLink.href = '/account/login?returnUrl=' + currentUrl;
      accountText.textContent = '로그인';
      if (signupLink) {
        signupLink.style.display = 'block';
        signupLink.href = '/account/register?returnUrl=' + currentUrl;
      }
    }
  }

  const parentButtons = drawer.querySelectorAll('[data-parent-button]');
  const contentPanels = drawer.querySelectorAll('[data-content-panel]');
  const searchCloseBtn = drawer.querySelector('[data-search-close]');
  const searchInput = drawer.querySelector('[data-search-input]');

  // Handle parent button clicks
  parentButtons.forEach(button => {
    button.addEventListener('click', function(e) {
      const linkHandle = this.getAttribute('data-link-handle');
      if (!linkHandle) return;

      // Check if there's a corresponding content panel
      const targetPanel = drawer.querySelector(`#menu-drawer-content-${linkHandle}`);

      // If no content panel exists, this item has no children - let onclick handle navigation
      if (!targetPanel) {
        return; // Allow default onclick navigation
      }

      // Prevent default and stop propagation to prevent drawer from closing
      e.preventDefault();
      e.stopPropagation();
      e.stopImmediatePropagation();

      // Remove active class from all buttons
      parentButtons.forEach(btn => {
        btn.classList.remove('menu-drawer__parent-button--active');
      });

      // Add active class to clicked button
      this.classList.add('menu-drawer__parent-button--active');

      // Hide all content panels
      contentPanels.forEach(panel => {
        panel.classList.remove('menu-drawer__content--active');
      });

      // Show corresponding content panel
      targetPanel.classList.add('menu-drawer__content--active');

      // Reset content panel scroll position
      const contentPanel = drawer.querySelector('.menu-drawer__content-panel');
      if (contentPanel) {
        contentPanel.scrollTop = 0;
      }

      // Scroll active tab into view
      this.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
    });
  });

  // Handle search close button
  if (searchCloseBtn) {
    searchCloseBtn.addEventListener('click', function(e) {
      // Close the entire menu drawer
      const details = drawer.querySelector('details[open]');
      if (details) {
        const summary = details.querySelector('summary');
        if (summary) {
          summary.click();
        }
      }
    });
  }

  // GNB 검색창 클릭 시 드로어 위에 검색 모달 열기
  const openSearchModalInput = drawer.querySelector('[data-open-search-modal]');
  if (openSearchModalInput) {
    openSearchModalInput.addEventListener('click', function(e) {
      e.preventDefault();
      const searchSummary = document.querySelector('details-modal.header__search summary');
      if (searchSummary) {
        searchSummary.click();
      }
    });
  }

  // Show first active content panel on load
  // URL 기반으로 활성 탭 결정 (upcoming-kids → kids 탭)
  const path = window.location.pathname;
  const pageTabMap = {
    '/pages/upcoming-kids': 'kids',
    '/pages/upcoming-fila': 'women'
  };
  const mappedHandle = pageTabMap[path];
  let initialButton = drawer.querySelector('[data-parent-button].menu-drawer__parent-button--active');

  if (!initialButton && mappedHandle) {
    initialButton = drawer.querySelector(`[data-parent-button][data-link-handle="${mappedHandle}"]`);
  }

  if (initialButton) {
    const linkHandle = initialButton.getAttribute('data-link-handle');
    if (linkHandle) {
      initialButton.classList.add('menu-drawer__parent-button--active');
      const targetPanel = drawer.querySelector(`#menu-drawer-content-${linkHandle}`);
      if (targetPanel) {
        targetPanel.classList.add('menu-drawer__content--active');
      }
    }
  } else if (parentButtons.length > 0) {
    // If no active button, activate first one
    const firstButton = parentButtons[0];
    const firstLinkHandle = firstButton.getAttribute('data-link-handle');
    if (firstLinkHandle) {
      firstButton.classList.add('menu-drawer__parent-button--active');
      const firstPanel = drawer.querySelector(`#menu-drawer-content-${firstLinkHandle}`);
      if (firstPanel) {
        firstPanel.classList.add('menu-drawer__content--active');
      }
    }
  }
})();

// dataLayer: gnb_menu — Mobile drawer 메뉴 클릭 추적
(function() {
  if (typeof FilaDL === 'undefined') return;
  var drawer = document.querySelector('header-drawer');
  if (!drawer) return;

  drawer.addEventListener('click', function(e) {
    // 1. Parent button with direct navigation (no children)
    var parentBtn = e.target.closest('[data-parent-button]');
    if (parentBtn) {
      var handle = parentBtn.getAttribute('data-link-handle');
      var panel = drawer.querySelector('#menu-drawer-content-' + handle);
      if (!panel) {
        FilaDL.push({
          event: 'gnb_menu',
          gnb: parentBtn.textContent.trim(),
          device: FilaDL.getDeviceShort()
        });
      }
      return;
    }

    // 2. Navigation links inside content panels
    var link = e.target.closest('a');
    if (!link) return;

    var slideGnbPath = link.getAttribute('data-dl-gnb');
    if (slideGnbPath) {
      FilaDL.push({
        event: 'gnb_menu',
        gnb: slideGnbPath,
        device: FilaDL.getDeviceShort()
      });
      return;
    }

    // Skip non-navigation links
    if (link.closest('.menu-drawer__nav-bottom')) return;
    if (link.closest('.menu-drawer__utility-links')) return;
    if (link.closest('.menu-drawer__content-slider')) return;

    var contentPanel = link.closest('[data-content-panel]');
    if (!contentPanel) return;

    // Get top-level name from the active parent button
    var activeBtn = drawer.querySelector('.menu-drawer__parent-button--active');
    var topLevel = activeBtn ? activeBtn.textContent.trim() : '';
    if (!topLevel) return;

    // Get link display text
    var linkSpans = link.querySelectorAll('span');
    var linkText = '';
    if (linkSpans.length > 0) {
      linkText = linkSpans[0].textContent.trim();
    }
    if (!linkText) linkText = link.textContent.trim();

    var gnbPath = '';

    // Grandchild link (inside accordion)
    var grandchildItem = link.closest('.menu-drawer__grandchild-item');
    if (grandchildItem) {
      var childDetails = grandchildItem.closest('.menu-drawer__child-details');
      var childSummary = childDetails ? childDetails.querySelector('.menu-drawer__child-text') : null;
      var childText = childSummary ? childSummary.textContent.trim() : '';
      gnbPath = topLevel + ' > ' + childText + ' > ' + linkText;
    }
    // Quick link
    else if (link.closest('.menu-drawer__quick-link-item')) {
      gnbPath = topLevel + ' > ' + linkText;
    }
    // Direct child link
    else if (link.classList.contains('menu-drawer__child-link')) {
      gnbPath = topLevel + ' > ' + linkText;
    }

    if (gnbPath) {
      FilaDL.push({
        event: 'gnb_menu',
        gnb: gnbPath,
        device: FilaDL.getDeviceShort()
      });
    }
  });
})();

(function(){
  /* ---------- Flags: helpers (safe) ---------- */

  // Convert 2-letter ISO code to emoji flag (works everywhere)
  function isoToFlagEmoji(iso){
    if (!iso) return '';
    return iso.toUpperCase().replace(/./g, function(c){
      return String.fromCodePoint(127397 + c.charCodeAt(0));
    });
  }

  // Minimal name -> ISO map; extend as needed
  var NAME_TO_ISO = {
    'united kingdom': 'GB',
    'european union': 'EU',
    'south africa':   'ZA',
    'china':          'CN',
    'indonesia':      'ID',
    'japan':          'JP',
    'philippines':    'PH',
    'india':          'IN',
    'malaysia':       'MY',
    'thailand':       'TH',
    'vietnam':        'VN',
    'singapore':      'SG',
    'taiwan':         'TW',
    'hong kong':      'HK',
    'south korea':    'KR',
    'korea':          'KR',
    'united states':  'US',
    'usa':            'US',
    'canada':         'CA',
    'mexico':         'MX',
    'australia':      'AU',
    'new zealand':    'NZ',
    'united arab emirates': 'AE',
    'uae':            'AE',
    'saudi arabia':   'SA',
    'qatar':          'QA',
    'kuwait':         'KW',
    'europe':         'EU'
  };

  // Keep it simple: lowercase, trim (no emoji stripping needed)
  function normalizeLabel(str){
    return (str || '').replace(/\s+/g, ' ').trim().toLowerCase();
  }

  // Inject flag spans before link text (idempotent + error-proof)
  function injectFlags(root){
    try {
      var links = root.querySelectorAll('.global-sites-list__link');
      links.forEach ? links.forEach(addFlag) : Array.prototype.forEach.call(links, addFlag);
    } catch (err) {
      // Never block the popup if anything goes wrong
      console.warn('[GlobalSites] Flag inject skipped:', err);
    }

    function addFlag(a){
      if (a.querySelector('.global-sites-list__flag')) return; // already added
      var label = normalizeLabel(a.textContent);
      var iso = NAME_TO_ISO[label];
      if (!iso) return;
      var el = document.createElement('span');
      el.className = 'global-sites-list__flag';
      el.textContent = isoToFlagEmoji(iso);
      a.prepend(el);
    }
  }

  /* ---------- Popup/accordion init ---------- */
  function initGlobalSitesSection(sectionRoot){
    if (!sectionRoot || sectionRoot.__gsInitialized) return;
    sectionRoot.__gsInitialized = true;

    var dialog      = sectionRoot.querySelector('[data-global-sites-dialog]');
    var overlay     = sectionRoot.querySelector('[data-global-sites-overlay]');
    var closeButton = sectionRoot.querySelector('[data-global-sites-close]');
    var sectionId   = sectionRoot.getAttribute('data-section-id');

    // Move dialog & overlay to body to avoid stacking context issues (e.g. PDP footer-group z-index)
    if (dialog && dialog.parentElement !== document.body) {
      document.body.appendChild(dialog);
    }
    if (overlay && overlay.parentElement !== document.body) {
      document.body.appendChild(overlay);
    }

    var focusCloseOnOpen = function(){ if (closeButton) closeButton.focus(); };

    function openPopup(){
      if (!dialog || !overlay) return;
      dialog.classList.add('is-open');
      overlay.classList.add('is-open');
      dialog.hidden  = false;
      overlay.hidden = false;
      document.body.style.overflow = 'hidden';
      setTimeout(focusCloseOnOpen, 0);
    }

    function closePopup(){
      if (!dialog || !overlay) return;
      dialog.classList.remove('is-open');
      overlay.classList.remove('is-open');
      document.body.style.overflow = '';
      setTimeout(function(){
        dialog.hidden  = true;
        overlay.hidden = true;
      }, 200);
    }

    // Open from any element with data-global-sites-open (optionally scoped)
    sectionRoot.__gsOpenerHandler = function(e){
      var opener = e.target.closest && e.target.closest('[data-global-sites-open]');
      if (!opener) return;
      var targetId = opener.getAttribute('data-global-sites-open');
      var matchesThis = !targetId || targetId === sectionId;
      if (matchesThis){
        e.preventDefault();
        openPopup();
      }
    };
    document.addEventListener('click', sectionRoot.__gsOpenerHandler);

    // Close handlers
    if (overlay) overlay.addEventListener('click', closePopup);
    if (closeButton) closeButton.addEventListener('click', closePopup);
    sectionRoot.__gsKeyHandler = function(e){
      if (e.key === 'Escape' && dialog && dialog.classList.contains('is-open')) closePopup();
    };
    document.addEventListener('keydown', sectionRoot.__gsKeyHandler);

    // Accordion (query from dialog since it was moved to document.body)
    var toggles = dialog.querySelectorAll('[data-global-sites-accordion-toggle]');
    (toggles.forEach ? toggles.forEach : Array.prototype.forEach).call(toggles, function(btn){
      var panel = btn.closest('.global-sites-accordion').querySelector('[data-global-sites-accordion-panel]');
      var setOpen = function(state){
        btn.setAttribute('aria-expanded', state ? 'true' : 'false');
        panel.style.gridTemplateRows = state ? '1fr' : '0fr';
      };
      setOpen(btn.getAttribute('aria-expanded') === 'true');
      btn.addEventListener('click', function(){
        setOpen(btn.getAttribute('aria-expanded') !== 'true');
      });
    });

    // Add flags after DOM is present for this section
    injectFlags(dialog);
  }

  // Init on normal page load
  document.addEventListener('DOMContentLoaded', function(){
    var roots = document.querySelectorAll('[data-global-sites-root]');
    (roots.forEach ? roots.forEach : Array.prototype.forEach).call(roots, initGlobalSitesSection);
  });

  // Init when Theme Editor injects/updates the section
  document.addEventListener('shopify:section:load', function(evt){
    var root = evt.target.querySelector('[data-global-sites-root]');
    if (root) initGlobalSitesSection(root);
  });

  // Cleanup when section is removed in editor
  document.addEventListener('shopify:section:unload', function(evt){
    var root = evt.target.querySelector('[data-global-sites-root]');
    if (root && root.__gsInitialized){
      document.removeEventListener('click', root.__gsOpenerHandler);
      document.removeEventListener('keydown', root.__gsKeyHandler);
      root.__gsInitialized = false;
    }
  });
})();

body.script:
  document.addEventListener('DOMContentLoaded', function () {
    const siteSelect = document.querySelector('[data-family-site-select]');
    if (siteSelect) {
      siteSelect.addEventListener('change', function () {
        const url = this.value;
        if (url && url !== '') {
          window.open(url, '_blank');
          this.selectedIndex = 0;
        }
      });
    }
    const tooltipImageSrcEl = document.querySelector('[data-legal-tooltip-image] img');
    if (tooltipImageSrcEl) {
      // Create desktop hover tooltip image
      const imgTooltip = document.createElement('img');
      imgTooltip.className = 'footer-legal__tooltip-image';
      imgTooltip.src = tooltipImageSrcEl.src;
      document.body.appendChild(imgTooltip);

      // Create mobile popup overlay
      const mobileOverlay = document.createElement('div');
      mobileOverlay.className = 'footer-legal__tooltip-overlay';
      mobileOverlay.innerHTML = '
'
        + ''
        + '×'
        + '';
      document.body.appendChild(mobileOverlay);

      mobileOverlay.addEventListener('click', function(e) {
        if (e.target === mobileOverlay || e.target.closest('.footer-legal__tooltip-close')) {
          mobileOverlay.classList.remove('is-active');
        }
      });

      var isTouchDevice = 'ontouchstart' in window || navigator.maxTouchPoints > 0;

      // Collect all tooltip trigger links
      var allLinks = [];
      document.querySelectorAll('[data-legal-tooltip] a[href]').forEach(function(a) { allLinks.push(a); });
      document.querySelectorAll('.footer-mobile-copyright a, .footer-legal-v2__copyright a').forEach(function(a) {
        if (a.textContent.indexOf('자세히') !== -1) allLinks.push(a);
      });

      allLinks.forEach(function(link) {
        link.addEventListener('click', function(e) {
          e.preventDefault();
          if (isTouchDevice) {
            mobileOverlay.classList.add('is-active');
          }
        });

        link.addEventListener('mouseenter', function() {
          if (!isTouchDevice) imgTooltip.style.display = 'block';
        });

        link.addEventListener('mouseleave', function() {
          if (!isTouchDevice) imgTooltip.style.display = 'none';
        });
      });
    }


  });

