document.addEventListener('DOMContentLoaded', function () {
  // Custom Studio 연동: ?open_cart=true 파라미터로 카트 자동 오픈
  const params = new URLSearchParams(window.location.search);
  if (params.get('open_cart') === 'true') {
    const cartType = params.get('cart_type') || 'NORMAL';
    const isAdded = params.get('is_added') === 'true';

    console.log('[Theme] open_cart detected, saving to localStorage:', { cartType, isAdded });

    // localStorage에 저장 (React 앱에서 마운트 시 확인)
    localStorage.setItem(
      'FILA_OPEN_CART',
      JSON.stringify({
        cartType: cartType,
        isAdded: isAdded,
        timestamp: Date.now(),
      })
    );

    // URL 파라미터 정리
    const url = new URL(window.location.href);
    url.searchParams.delete('open_cart');
    url.searchParams.delete('cart_type');
    url.searchParams.delete('is_added');
    history.replaceState({}, '', url.pathname + url.search + url.hash);
  }
});

/* Kakao SDK가 defer로 로드되므로 DOMContentLoaded 이후 초기화 */
function _initKakao() {
  if (typeof Kakao !== 'undefined' && !Kakao.isInitialized()) {
    Kakao.init('417d30c332f49381efb9254f00c682fc');
  }
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', _initKakao);
} else {
  _initKakao();
}

function chatChannel() {
  if (typeof Kakao === 'undefined') return;
  if (!Kakao.isInitialized()) Kakao.init('417d30c332f49381efb9254f00c682fc');
  Kakao.Channel.chat({
    channelPublicId: '_aNxaCu',
  });
}

(function() {
  var kakaoBtn = document.querySelector('.kakao-chat-button');
  var scrollToTopBtn = document.querySelector('.scroll-to-top');

  window.addEventListener('scroll', function() {
    var scrollPercent = (window.scrollY / (document.documentElement.scrollHeight - window.innerHeight)) * 100;
    if (scrollPercent >= 5) {
      kakaoBtn.classList.add('visible');
      scrollToTopBtn.classList.add('visible');
    } else {
      kakaoBtn.classList.remove('visible');
      scrollToTopBtn.classList.remove('visible');
    }
  }, { passive: true });

  // 바텀시트 열림/닫힘 감지
  var observer = new MutationObserver(function(mutations) {
    var sheetOpen = document.querySelector('div[role="dialog"][data-state="open"]');
    if (sheetOpen) {
      document.body.classList.add('sheet-open');
    } else {
      document.body.classList.remove('sheet-open');
    }
  });
  observer.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['data-state'] });
})();

